/** Branding, real preset application, portable themes and Run integration. */
public class TenThemeSmoke extends Instrumentation {
    MainActivity home;View root;DesktopStore store;
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();try{
        store=new DesktopStore(getTargetContext());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("taskbar_apps",false).putBoolean("ten_full_start",false).putString("ten_nota_draft","").commit();TenThemes.TEN.get(0).apply(store);
        getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();await(()->TenSmoke.description(root,"Start menu")!=null,"Shell ready");
        branding();themes();portable();run();
        ui(()->{TenThemes.TEN.get(0).apply(store);home.applyTenAppearance();home.open("@taskmanager");View performance=TenSmoke.description(root,"Task Manager Performance");check(performance!=null,"Performance tab available");performance.performClick();});shot("ten4-performance");
        result.putString("stream","PASS: N-to-the-tenth application/Start branding, visible 17-theme gallery, Ten light/transparency and Aero application without replacing windows, saved theme pack/unpack with legacy Seven compatibility, new backup preferences and invalid-value rejection, native Run/keyboard shortcut/history\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable error){try{shot("ten4-failure");}catch(Exception ignored){}result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
    void branding()throws Exception{ui(()->{check(TenSmoke.description(root,"Start menu") instanceof TenBrandMark,"Start uses common N10 mark");Drawable icon=getTargetContext().getApplicationInfo().loadIcon(getTargetContext().getPackageManager());Bitmap b=Bitmap.createBitmap(108,108,Bitmap.Config.ARGB_8888);icon.setBounds(0,0,108,108);icon.draw(new Canvas(b));int black=0,white=0,colorful=0;for(int y=0;y<108;y++)for(int x=0;x<108;x++){int color=b.getPixel(x,y);if(Color.alpha(color)<200)continue;int r=Color.red(color),g=Color.green(color),blue=Color.blue(color);if(Math.max(r,Math.max(g,blue))<85)black++;if(Math.min(r,Math.min(g,blue))>205)white++;if(Math.max(r,Math.max(g,blue))-Math.min(r,Math.min(g,blue))>45)colorful++;}b.recycle();check(black>4000&&white>300&&colorful<100,"Application icon is black with a white mark, not the blue Seven pearl");home.open("@settings");((TenSettings)windows().get("@settings").body).navigate("about");Toast.makeText(home,"N¹⁰ branding preview",Toast.LENGTH_LONG).show();});SystemClock.sleep(350);shot("ten4-brand-toast");ui(()->{StartMenu start=TenSmoke.find(root,StartMenu.class);start.show(false);check(start.getBackground() instanceof AeroGlass,"Opening Start preserves its live theme surface");});shot("ten4-start-brand");}
    void themes()throws Exception{ui(()->{home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);home.open("@notes");((EditText)TenSmoke.description(windows().get("@notes"),"Notepad text")).setText("Theme changes keep my document");home.open("ten-setting:themes");});await(()->root.getWidth()>root.getHeight(),"Landscape");await(()->TenSmoke.find(root,TenThemeGallery.class)!=null,"Theme gallery is native");DesktopWindow note=windows().get("@notes");ui(()->{TenThemeGallery gallery=TenSmoke.find(root,TenThemeGallery.class);check(count(gallery,"Apply theme:")==17,"Eight Ten and nine Aero presets");TenSmoke.description(gallery,"Apply theme: Ten Light").performClick();check(store.prefs.getBoolean("ten_light",false),"Light shell applied");check(windows().get("@notes")==note&&store.prefs.getString("note","").equals("Theme changes keep my document"),"Live application keeps window and document");check(((TenSettings)windows().get("@settings").body).page.equals("themes"),"Themes remains selected");});await(()->{View card=TenSmoke.description(TenSmoke.find(root,TenThemeGallery.class),"Apply theme: Ten Blue");return card!=null&&card.getGlobalVisibleRect(new Rect());},"Theme cards appear without scrolling");shot("ten4-themes-ten");ui(()->{TenSmoke.description(TenSmoke.find(root,TenThemeGallery.class),"Apply theme: Ten Midnight").performClick();check(store.prefs.getBoolean("ten_transparency",false),"Ten transparency applied");TenSmoke.description(TenSmoke.find(root,TenThemeGallery.class),"Apply theme: Meadow").performClick();check(TenThemes.aero(store.prefs)&&store.prefs.getInt("aero_color",-1)==3,"Aero theme uses actual glass tint");home.open("@search");check(TenSmoke.find(root,StartMenu.class).getBackground() instanceof AeroGlass,"Aero Start stays glass when opened");});shot("ten4-aero-start");ui(()->{home.open("ten-setting:colors");});shot("ten4-colors");}
    void portable()throws Exception{final JSONObject[] profile={null};ui(()->{try{profile[0]=ThemeProfiles.capture(store,"Aero portability fixture");byte[] bytes=ThemeProfiles.pack(home,profile[0]);JSONObject decoded=ThemeProfiles.unpack(home,new ByteArrayInputStream(bytes));TenThemes.TEN.get(1).apply(store);ThemeProfiles.apply(store,decoded);check(TenThemes.aero(store.prefs)&&store.prefs.getInt("aero_color",-1)==3,"Portable theme retains Ten shell fields");for(String key:new String[]{"ten_shell_style","ten_accent","ten_light","ten_transparency","ten_accent_shell","ten_accent_titles"})decoded.remove(key);ThemeProfiles.apply(store,decoded);check(TenThemes.aero(store.prefs),"Legacy Seven theme imports as Aero");ThemeProfiles.add(store,profile[0]);home.applyTenAppearance();home.open("ten-setting:themes");check(TenSmoke.description(root,"Saved theme: Aero portability fixture")!=null,"Saved theme appears natively");store.prefs.edit().putString("ten_news_mode","Icon").putBoolean("ten_news_hover",true).putBoolean("ten_news_images",true).putString("ten_saved_news","[{\"title\":\"Saved fixture\",\"url\":\"https://example.com/story\"}]").putString("ten_run_history","[\"notepad\"]").commit();JSONObject snapshot=DesktopBackup.snapshot(store);DesktopBackup.Plan plan=DesktopBackup.parse(snapshot.toString());check(plan.values.get("ten_news_mode").equals("Icon")&&plan.values.containsKey("ten_shell_style")&&plan.values.containsKey("ten_saved_news")&&plan.values.containsKey("ten_run_history"),"New preferences included in backup");snapshot.getJSONObject("settings").getJSONObject("ten_news_mode").put("value","invalid");boolean rejected=false;try{DesktopBackup.parse(snapshot.toString());}catch(JSONException expected){rejected=true;}check(rejected&&store.prefs.getString("ten_news_mode","").equals("Icon"),"Invalid backup rejected without changing live settings");}catch(Exception e){throw new RuntimeException(e);}});shot("ten4-themes-saved");}
    void run()throws Exception{ui(()->home.dispatchKeyEvent(new KeyEvent(0,0,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_R,0,KeyEvent.META_META_ON)));awaitSystem("Run command");setSystemText("Run command","notepad");systemClick("OK");await(()->windows().get("@notes").getVisibility()==View.VISIBLE,"Run opens real Notepad");check(store.prefs.getString("ten_run_history","").contains("notepad"),"Run history saved");ui(()->{check(home.runCommand("ms-settings:themes"),"Settings command resolves");check(!home.runCommand("unknown-app; rm -rf /"),"Unknown command is not executed");home.open("@run");});shot("ten4-run");systemClick("Cancel");}
    int count(View view,String prefix){int n=view.getContentDescription()!=null&&view.getContentDescription().toString().startsWith(prefix)?1:0;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)n+=count(((ViewGroup)view).getChildAt(i),prefix);return n;}
    @SuppressWarnings("unchecked") Map<String,DesktopWindow> windows(){try{Field field=MainActivity.class.getDeclaredField("windows");field.setAccessible(true);return(Map<String,DesktopWindow>)field.get(home);}catch(Exception e){throw new RuntimeException(e);}}
    interface Condition{boolean get();}void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}void ui(Runnable run)throws Exception{FutureTask<Void> task=new FutureTask<>(run,null);home.runOnUiThread(task);task.get(20,TimeUnit.SECONDS);}void await(Condition condition,String why)throws Exception{long end=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<end){FutureTask<Boolean> task=new FutureTask<>(condition::get);home.runOnUiThread(task);if(task.get(10,TimeUnit.SECONDS))return;Thread.sleep(80);}throw new AssertionError(why);}
    void shot(String name)throws Exception{waitForIdleSync();SystemClock.sleep(200);Bitmap b=getUiAutomation().takeScreenshot();if(b!=null)try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
    AccessibilityNodeInfo node(AccessibilityNodeInfo current,String text){if(current==null)return null;if(text.contentEquals(current.getText()==null?"":current.getText())||text.contentEquals(current.getContentDescription()==null?"":current.getContentDescription()))return current;for(int i=0;i<current.getChildCount();i++){AccessibilityNodeInfo found=node(current.getChild(i),text);if(found!=null)return found;}return null;}
    AccessibilityNodeInfo awaitSystem(String text)throws Exception{long end=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<end){AccessibilityNodeInfo found=node(getUiAutomation().getRootInActiveWindow(),text);if(found!=null)return found;Thread.sleep(80);}throw new AssertionError("Missing system field "+text);}
    void setSystemText(String label,String text)throws Exception{AccessibilityNodeInfo field=awaitSystem(label);Bundle args=new Bundle();args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,text);check(field.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args),"Run entry accepts text");waitForIdleSync();}
    void systemClick(String label)throws Exception{AccessibilityNodeInfo found=awaitSystem(label);Rect r=new Rect();found.getBoundsInScreen(r);long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,0,r.centerX(),r.centerY(),0),up=MotionEvent.obtain(now,now+60,1,r.centerX(),r.centerY(),0);sendPointerSync(down);sendPointerSync(up);down.recycle();up.recycle();waitForIdleSync();}
}
